import { ChevronDown } from "lucide-react";
import type { ReactNode } from "react";

import { useTranslate } from "../../../i18n/use-translate";
import type { WorkoutFileFormat } from "../../../utils/file-format-detector";
import { type FormatOption, getFileExtensionForFormat } from "./format-options";

type FormatDropdownButtonProps = {
  readonly currentFormat: WorkoutFileFormat;
  readonly currentOption: FormatOption | undefined;
  readonly isOpen: boolean;
  readonly onToggle: () => void;
  readonly disabled: boolean;
  /** Shown instead of the current format when the menu itself is the action. */
  readonly label?: ReactNode;
};

export function FormatDropdownButton({
  currentFormat,
  currentOption,
  isOpen,
  onToggle,
  disabled,
  label,
}: FormatDropdownButtonProps) {
  const t = useTranslate("editor");
  return (
    <button
      type="button"
      onClick={onToggle}
      disabled={disabled}
      className={`
        w-full sm:w-auto flex items-center justify-between gap-2 px-4 py-2.5
        bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600
        rounded-lg text-sm font-medium text-gray-900 dark:text-gray-100
        hover:bg-gray-50 dark:hover:bg-gray-700
        focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2
        disabled:opacity-60 disabled:cursor-not-allowed
        transition-colors whitespace-nowrap
      `}
      aria-label={label ? undefined : t("exportFormat.selectAria")}
      aria-expanded={isOpen}
      aria-haspopup="menu"
      data-testid="export-format-selector-button"
    >
      {label ?? (
        <span className="flex items-center gap-2">
          <span className="font-semibold">{currentOption?.label}</span>
          <span className="text-gray-500 dark:text-gray-400">
            (.{getFileExtensionForFormat(currentFormat)})
          </span>
        </span>
      )}
      <ChevronDown
        className={`h-4 w-4 transition-transform ${isOpen ? "rotate-180" : ""}`}
      />
    </button>
  );
}
